INSERT INTO public.roles (role_id, role_code, role_name, institutional_scope, description, allowed_actions, can_be_assigned_tickets, can_publish_policies, can_approve_escalations, effective_from, effective_to, created_at)
VALUES
  ('ROLE-LEARNER', 'learner', 'Learner', 'Undergraduate & Graduate Student Cohort', 'Submits academic and support requests, queries policy-grounded answers, and provides resolution feedback.', ARRAY['submit_academic_petition']::text[], FALSE, FALSE, FALSE, '2025-08-01', NULL, '2026-09-01T08:00:00.000Z'),
  ('ROLE-INSTRUCTOR', 'instructor', 'Instructor', 'Faculty & Course Instructional Staff', 'Submits course-related requests, attests to student petitions, and proposes policy revisions.', ARRAY['submit_faculty_course_request', 'propose_policy_revision']::text[], FALSE, FALSE, FALSE, '2025-08-01', NULL, '2026-09-01T08:00:00.000Z'),
  ('ROLE-SUPPORT_STAFF', 'support_staff', 'Support Staff', 'Operational Intake & Departmental Triage Units', 'Triages incoming tickets, verifies applicable policy versions, responds to routine inquiries, and escalates exceptions.', ARRAY['log_intake_support_ticket', 'triage_support_queue', 'propose_policy_revision']::text[], TRUE, FALSE, FALSE, '2025-08-01', NULL, '2026-09-01T08:00:00.000Z'),
  ('ROLE-ACADEMIC_ADMIN', 'academic_administrator', 'Academic Administrator', 'Academic Governance & Escalation Review Boards', 'Adjudicates escalated requests, approves policy exceptions, and publishes authoritative policy documents.', ARRAY['initiate_administrative_review', 'approve_policy_escalation', 'publish_knowledge_article', 'configure_department_routing']::text[], TRUE, TRUE, TRUE, '2025-08-01', NULL, '2026-09-01T08:00:00.000Z'),
  ('ROLE-PLATFORM_ADMIN', 'platform_administrator', 'Platform Administrator', 'Enterprise Workflow, Routing & SLA Governance', 'Configures routing rules, SLA schedules, and platform security governance.', ARRAY['initiate_administrative_review', 'publish_knowledge_article', 'configure_department_routing', 'configure_platform_governance']::text[], TRUE, TRUE, TRUE, '2025-08-01', NULL, '2026-09-01T08:00:00.000Z')
