INSERT INTO public.categories (category_id, category_name, domain_code, default_assigned_team, escalation_team, routing_rule_id, description, keywords, is_active, effective_from, effective_to, created_at)
VALUES
  ('CAT-FINAID', 'Financial Aid', 'FINAID', 'Office of Financial Aid & Scholarships', 'Financial Aid Appeals & Compliance Review Committee', 'RULE-FINAID-001', 'Routes Financial Aid disbursement, SAP appeal, scholarship eligibility, and emergency aid inquiries to the Office of Financial Aid & Scholarships; escalates appeals and policy exceptions to the Financial Aid Appeals & Compliance Review Committee.', ARRAY['fafsa', 'sap', 'appeal', 'disbursement', 'scholarship', 'grant']::text[], TRUE, '2025-08-01', NULL, '2026-09-01T08:00:00.000Z'),
  ('CAT-REG', 'Registration', 'REG', 'Office of the University Registrar', 'Academic Senate Registration Review Board', 'RULE-REG-001', 'Routes course enrollment, add/drop deadlines, late withdrawal petitions, credit overload, and degree audit requests to the Office of the University Registrar; escalates retroactive petitions to the Academic Senate Registration Review Board.', ARRAY['add/drop', 'withdrawal', 'overload', 'prerequisite', 'enrollment']::text[], TRUE, '2025-08-01', NULL, '2026-09-01T08:00:00.000Z'),
  ('CAT-IT', 'IT', 'IT', 'Campus IT Operations & Identity Desk', 'Information Security & Infrastructure Escalation Unit', 'RULE-IT-001', 'Routes SSO authentication, MFA reset, LMS access, institutional email provisioning, and lab software licensing requests to the Campus IT Operations & Identity Desk; escalates security or multi-system outages to Information Security & Infrastructure Escalation Unit.', ARRAY['mfa', 'sso', 'lms', 'password', 'authenticator', 'license']::text[], TRUE, '2025-08-01', NULL, '2026-09-01T08:00:00.000Z'),
  ('CAT-ACCESS', 'Accessibility', 'ACCESS', 'Disability & Accessibility Services Office', 'ADA / Section 504 Compliance Review Panel', 'RULE-ACCESS-001', 'Routes exam accommodation letters, assistive technology requests, captioning, and physical classroom access adjustments to the Disability & Accessibility Services Office; escalates accommodation disputes or urgent compliance barriers to the ADA / Section 504 Compliance Review Panel.', ARRAY['accommodation', 'testing', 'captioning', 'assistive', 'section 504']::text[], TRUE, '2025-08-01', NULL, '2026-09-01T08:00:00.000Z')
