INSERT INTO public.policy_documents (policy_id, domain, category_id, title, version, effective_date, expiration_date, lifecycle_state, supersedes_policy_id, superseded_by_policy_id, summary, content, authoritative_section_ref, source_name, source_url, dataset_or_doc_version, retrieval_date, license_terms, attribution, transformations_performed, discarded_fields, is_synthetic_policy, published_by_profile_id, created_at, updated_at)
VALUES
  ('POL-FINAID-2026-001', 'FINAID', 'CAT-FINAID', 'Satisfactory Academic Progress (SAP) & Financial Aid Appeal Policy (Legacy)', '1.0', '2025-01-01', '2026-06-30', 'expired', NULL, 'POL-FINAID-2026-002', '[SYNTHETIC DEMONSTRATION POLICY — EXPIRED] Legacy SAP appeal deadline rules effective through June 30, 2026.', '[SYNTHETIC DEMONSTRATION POLICY] Under legacy version 1.0 (expired 2026-06-30), students placed on financial aid suspension had 10 calendar days from term start to submit a Satisfactory Academic Progress (SAP) appeal with supporting documentation to the Office of Financial Aid & Scholarships.', 'Section 4.1 (Superseded)', 'CampusResolve AI Synthetic Policy Corpus (YottaFlex Challenge)', 'urn:campusresolve:synthetic-policy:pol-finaid-2026-001', '2026.10-seed-20261022-v1.0', '2026-09-01', 'CC0-1.0 Synthetic Demonstration & Evaluation Corpus (Non-Regulatory)', 'Synthetic university policy created strictly for CampusResolve AI evaluation; not real institutional regulation.', 'Normalized section headers, tagged effective/expiration dates, and linked superseding policy IDs.', 'legacy_pdf_page_checksum', TRUE, NULL, '2025-01-01T08:00:00.000Z', '2026-09-01T08:00:00.000Z'),
  ('POL-FINAID-2026-002', 'FINAID', 'CAT-FINAID', 'Satisfactory Academic Progress (SAP) & Financial Aid Appeal Policy', '2.0', '2026-07-01', NULL, 'active', 'POL-FINAID-2026-001', NULL, '[SYNTHETIC DEMONSTRATION POLICY — ACTIVE] Current SAP appeal requirements, 15-business-day submission window, and committee escalation rules.', '[SYNTHETIC DEMONSTRATION POLICY] Effective July 1, 2026 (Version 2.0, superseding POL-FINAID-2026-001 v1.0), students whose cumulative GPA falls below 2.0 or pace of completion falls below 67% may submit a written Satisfactory Academic Progress (SAP) appeal within 15 business days of notification. Standard eligibility verifications are handled by the Office of Financial Aid & Scholarships; second-level SAP appeals and emergency statutory waivers must be escalated to the Financial Aid Appeals & Compliance Review Committee.', 'Section 4.2 (Current)', 'CampusResolve AI Synthetic Policy Corpus (YottaFlex Challenge)', 'urn:campusresolve:synthetic-policy:pol-finaid-2026-002', '2026.10-seed-20261022-v2.0', '2026-09-01', 'CC0-1.0 Synthetic Demonstration & Evaluation Corpus (Non-Regulatory)', 'Synthetic university policy created strictly for CampusResolve AI evaluation; not real institutional regulation.', 'Normalized section headers, tagged effective/expiration dates, and linked superseding policy IDs.', 'legacy_pdf_page_checksum', TRUE, NULL, '2026-07-01T08:00:00.000Z', '2026-09-01T08:00:00.000Z'),
  ('POL-FINAID-2026-003', 'FINAID', 'CAT-FINAID', 'Term Aid Disbursement & Census Date Proration Policy', '1.0', '2026-01-15', NULL, 'active', NULL, NULL, '[SYNTHETIC DEMONSTRATION POLICY — ACTIVE] Rules governing grant/scholarship disbursement timing and enrollment intensity proration at census date.', '[SYNTHETIC DEMONSTRATION POLICY] Institutional grants and federal aid disburse no earlier than 10 days prior to the official term start date, contingent upon active enrollment in at least 6 credit hours for half-time status or 12 credit hours for full-time status locked at the add/drop census deadline.', 'Section 2.3', 'CampusResolve AI Synthetic Policy Corpus (YottaFlex Challenge)', 'urn:campusresolve:synthetic-policy:pol-finaid-2026-003', '2026.10-seed-20261022-v1.0', '2026-09-01', 'CC0-1.0 Synthetic Demonstration & Evaluation Corpus (Non-Regulatory)', 'Synthetic university policy created strictly for CampusResolve AI evaluation; not real institutional regulation.', 'Normalized section headers, tagged effective/expiration dates, and linked superseding policy IDs.', 'legacy_pdf_page_checksum', TRUE, NULL, '2026-01-15T08:00:00.000Z', '2026-09-01T08:00:00.000Z'),
  ('POL-REG-2026-001', 'REG', 'CAT-REG', 'Course Add/Drop & Late Withdrawal Petition Policy (Legacy)', '1.0', '2025-01-01', '2026-05-31', 'expired', NULL, 'POL-REG-2026-002', '[SYNTHETIC DEMONSTRATION POLICY — EXPIRED] Legacy course drop and withdrawal rules effective through May 31, 2026.', '[SYNTHETIC DEMONSTRATION POLICY] Under legacy version 1.0 (expired 2026-05-31), students could drop courses without a W grade through Week 3 of the semester.', 'Section 3.1 (Superseded)', 'CampusResolve AI Synthetic Policy Corpus (YottaFlex Challenge)', 'urn:campusresolve:synthetic-policy:pol-reg-2026-001', '2026.10-seed-20261022-v1.0', '2026-09-01', 'CC0-1.0 Synthetic Demonstration & Evaluation Corpus (Non-Regulatory)', 'Synthetic university policy created strictly for CampusResolve AI evaluation; not real institutional regulation.', 'Normalized section headers, tagged effective/expiration dates, and linked superseding policy IDs.', 'legacy_pdf_page_checksum', TRUE, NULL, '2025-01-01T08:00:00.000Z', '2026-09-01T08:00:00.000Z'),
  ('POL-REG-2026-002', 'REG', 'CAT-REG', 'Course Add/Drop & Late Withdrawal Petition Policy', '2.0', '2026-06-01', NULL, 'active', 'POL-REG-2026-001', NULL, '[SYNTHETIC DEMONSTRATION POLICY — ACTIVE] Current 10-business-day add/drop window, W-grade withdrawal deadline, and retroactive petition escalation.', '[SYNTHETIC DEMONSTRATION POLICY] Effective June 1, 2026 (Version 2.0, superseding POL-REG-2026-001 v1.0), standard course additions and drops without transcript notation must be completed within the first 10 business days of the term via the Office of the University Registrar. Course withdrawals with a W notation are permitted through the end of Week 8. Any retroactive withdrawal or late drop petition after Week 8 requires documented extenuating circumstances and mandatory escalation to the Academic Senate Registration Review Board.', 'Section 3.2 (Current)', 'CampusResolve AI Synthetic Policy Corpus (YottaFlex Challenge)', 'urn:campusresolve:synthetic-policy:pol-reg-2026-002', '2026.10-seed-20261022-v2.0', '2026-09-01', 'CC0-1.0 Synthetic Demonstration & Evaluation Corpus (Non-Regulatory)', 'Synthetic university policy created strictly for CampusResolve AI evaluation; not real institutional regulation.', 'Normalized section headers, tagged effective/expiration dates, and linked superseding policy IDs.', 'legacy_pdf_page_checksum', TRUE, NULL, '2026-06-01T08:00:00.000Z', '2026-09-01T08:00:00.000Z'),
  ('POL-REG-2026-003', 'REG', 'CAT-REG', 'Credit Overload & Cross-Departmental Prerequisite Override Policy', '1.0', '2026-01-10', NULL, 'active', NULL, NULL, '[SYNTHETIC DEMONSTRATION POLICY — ACTIVE] Maximum term credit cap (18 credits) and approval rules for 19–22 credit overload petitions.', '[SYNTHETIC DEMONSTRATION POLICY] Standard undergraduate enrollment is capped at 18 credit hours per regular term. Requests to enroll in 19 to 22 credit hours require a minimum cumulative GPA of 3.30 and advisor attestation processed by the Office of the University Registrar.', 'Section 5.4', 'CampusResolve AI Synthetic Policy Corpus (YottaFlex Challenge)', 'urn:campusresolve:synthetic-policy:pol-reg-2026-003', '2026.10-seed-20261022-v1.0', '2026-09-01', 'CC0-1.0 Synthetic Demonstration & Evaluation Corpus (Non-Regulatory)', 'Synthetic university policy created strictly for CampusResolve AI evaluation; not real institutional regulation.', 'Normalized section headers, tagged effective/expiration dates, and linked superseding policy IDs.', 'legacy_pdf_page_checksum', TRUE, NULL, '2026-01-10T08:00:00.000Z', '2026-09-01T08:00:00.000Z'),
  ('POL-IT-2026-001', 'IT', 'CAT-IT', 'Institutional Identity, SSO & Multi-Factor Authentication Policy (Legacy)', '1.0', '2025-01-01', '2026-04-30', 'expired', NULL, 'POL-IT-2026-002', '[SYNTHETIC DEMONSTRATION POLICY — EXPIRED] Legacy SMS-based two-factor reset rules expired April 30, 2026.', '[SYNTHETIC DEMONSTRATION POLICY] Under legacy version 1.0 (expired 2026-04-30), SMS text codes were permitted as a primary multi-factor authentication method for institutional accounts.', 'Section 1.1 (Superseded)', 'CampusResolve AI Synthetic Policy Corpus (YottaFlex Challenge)', 'urn:campusresolve:synthetic-policy:pol-it-2026-001', '2026.10-seed-20261022-v1.0', '2026-09-01', 'CC0-1.0 Synthetic Demonstration & Evaluation Corpus (Non-Regulatory)', 'Synthetic university policy created strictly for CampusResolve AI evaluation; not real institutional regulation.', 'Normalized section headers, tagged effective/expiration dates, and linked superseding policy IDs.', 'legacy_pdf_page_checksum', TRUE, NULL, '2025-01-01T08:00:00.000Z', '2026-09-01T08:00:00.000Z'),
  ('POL-IT-2026-002', 'IT', 'CAT-IT', 'Institutional Identity, SSO & Multi-Factor Authentication Policy', '2.0', '2026-05-01', NULL, 'active', 'POL-IT-2026-001', NULL, '[SYNTHETIC DEMONSTRATION POLICY — ACTIVE] Current hardware token / authenticator app MFA requirement and identity verification procedures.', '[SYNTHETIC DEMONSTRATION POLICY] Effective May 1, 2026 (Version 2.0, superseding POL-IT-2026-001 v1.0), all learners, instructors, and staff must use FIDO2 passkeys or TOTP authenticator apps for Single Sign-On (SSO). Routine MFA device resets are handled by the Campus IT Operations & Identity Desk after photo-ID verification. Suspected account compromise or privilege anomalies must be escalated immediately to the Information Security & Infrastructure Escalation Unit.', 'Section 1.2 (Current)', 'CampusResolve AI Synthetic Policy Corpus (YottaFlex Challenge)', 'urn:campusresolve:synthetic-policy:pol-it-2026-002', '2026.10-seed-20261022-v2.0', '2026-09-01', 'CC0-1.0 Synthetic Demonstration & Evaluation Corpus (Non-Regulatory)', 'Synthetic university policy created strictly for CampusResolve AI evaluation; not real institutional regulation.', 'Normalized section headers, tagged effective/expiration dates, and linked superseding policy IDs.', 'legacy_pdf_page_checksum', TRUE, NULL, '2026-05-01T08:00:00.000Z', '2026-09-01T08:00:00.000Z'),
  ('POL-IT-2026-003', 'IT', 'CAT-IT', 'LMS Course Shell Provisioning & Academic Software Licensing Policy', '1.0', '2026-01-15', NULL, 'active', NULL, NULL, '[SYNTHETIC DEMONSTRATION POLICY — ACTIVE] Automated LMS roster synchronization and instructional lab software seat allocation.', '[SYNTHETIC DEMONSTRATION POLICY] LMS course shells are provisioned 30 days before term start and synchronize roster changes every 4 hours with the Registrar feed. Special seat allocations for instructional lab software are fulfilled by the Campus IT Operations & Identity Desk.', 'Section 6.1', 'CampusResolve AI Synthetic Policy Corpus (YottaFlex Challenge)', 'urn:campusresolve:synthetic-policy:pol-it-2026-003', '2026.10-seed-20261022-v1.0', '2026-09-01', 'CC0-1.0 Synthetic Demonstration & Evaluation Corpus (Non-Regulatory)', 'Synthetic university policy created strictly for CampusResolve AI evaluation; not real institutional regulation.', 'Normalized section headers, tagged effective/expiration dates, and linked superseding policy IDs.', 'legacy_pdf_page_checksum', TRUE, NULL, '2026-01-15T08:00:00.000Z', '2026-09-01T08:00:00.000Z'),
  ('POL-ACCESS-2026-001', 'ACCESS', 'CAT-ACCESS', 'Academic Accommodations & Testing Notice Policy (Legacy)', '1.0', '2025-01-01', '2026-06-15', 'expired', NULL, 'POL-ACCESS-2026-002', '[SYNTHETIC DEMONSTRATION POLICY — EXPIRED] Legacy 14-day proctored testing notice requirement expired June 15, 2026.', '[SYNTHETIC DEMONSTRATION POLICY] Under legacy version 1.0 (expired 2026-06-15), students were required to submit proctored exam accommodation booking requests 14 calendar days prior to the examination date.', 'Section 7.1 (Superseded)', 'CampusResolve AI Synthetic Policy Corpus (YottaFlex Challenge)', 'urn:campusresolve:synthetic-policy:pol-access-2026-001', '2026.10-seed-20261022-v1.0', '2026-09-01', 'CC0-1.0 Synthetic Demonstration & Evaluation Corpus (Non-Regulatory)', 'Synthetic university policy created strictly for CampusResolve AI evaluation; not real institutional regulation.', 'Normalized section headers, tagged effective/expiration dates, and linked superseding policy IDs.', 'legacy_pdf_page_checksum', TRUE, NULL, '2025-01-01T08:00:00.000Z', '2026-09-01T08:00:00.000Z'),
  ('POL-ACCESS-2026-002', 'ACCESS', 'CAT-ACCESS', 'Academic Accommodations & Proctored Testing Notice Policy', '2.0', '2026-06-16', NULL, 'active', 'POL-ACCESS-2026-001', NULL, '[SYNTHETIC DEMONSTRATION POLICY — ACTIVE] Current 5-business-day proctored exam notice, accommodation letters, and Section 504 escalation.', '[SYNTHETIC DEMONSTRATION POLICY] Effective June 16, 2026 (Version 2.0, superseding POL-ACCESS-2026-001 v1.0), students holding approved accommodation letters from the Disability & Accessibility Services Office must submit proctored exam scheduling requests at least 5 business days before the exam. Accommodation implementation disputes, denials, or urgent barrier reports must be escalated to the ADA / Section 504 Compliance Review Panel.', 'Section 7.2 (Current)', 'CampusResolve AI Synthetic Policy Corpus (YottaFlex Challenge)', 'urn:campusresolve:synthetic-policy:pol-access-2026-002', '2026.10-seed-20261022-v2.0', '2026-09-01', 'CC0-1.0 Synthetic Demonstration & Evaluation Corpus (Non-Regulatory)', 'Synthetic university policy created strictly for CampusResolve AI evaluation; not real institutional regulation.', 'Normalized section headers, tagged effective/expiration dates, and linked superseding policy IDs.', 'legacy_pdf_page_checksum', TRUE, NULL, '2026-06-16T08:00:00.000Z', '2026-09-01T08:00:00.000Z'),
  ('POL-ACCESS-2026-003', 'ACCESS', 'CAT-ACCESS', 'Assistive Technology, Real-Time Captioning & Accessible Media Policy', '1.0', '2026-01-15', NULL, 'active', NULL, NULL, '[SYNTHETIC DEMONSTRATION POLICY — ACTIVE] Provisioning of screen-reader compatible course packets, CART captioning, and ergonomic classroom seating.', '[SYNTHETIC DEMONSTRATION POLICY] The Disability & Accessibility Services Office coordinates real-time CART captioning, Braille/tactile graphics conversion, and screen-reader accessible PDF remediation for enrolled learners within 3 business days of request intake.', 'Section 8.3', 'CampusResolve AI Synthetic Policy Corpus (YottaFlex Challenge)', 'urn:campusresolve:synthetic-policy:pol-access-2026-003', '2026.10-seed-20261022-v1.0', '2026-09-01', 'CC0-1.0 Synthetic Demonstration & Evaluation Corpus (Non-Regulatory)', 'Synthetic university policy created strictly for CampusResolve AI evaluation; not real institutional regulation.', 'Normalized section headers, tagged effective/expiration dates, and linked superseding policy IDs.', 'legacy_pdf_page_checksum', TRUE, NULL, '2026-01-15T08:00:00.000Z', '2026-09-01T08:00:00.000Z')
INSERT INTO public.knowledge_articles (article_id, category_id, primary_policy_id, primary_policy_version, title, version, effective_date, expiration_date, lifecycle_state, summary, content, tags, source_url, dataset_or_doc_version, retrieval_date, license_terms, attribution, transformations_performed, discarded_fields, is_synthetic_article, created_at, updated_at)
VALUES
  ('KB-000001', 'CAT-FINAID', 'POL-FINAID-2026-001', '1.0', 'SAP Pace of Completion Calculation & Appeal Packet Checklist (Ref POL-FINAID-2026-001 v1.0 · #1)', '1.0', '2025-01-01', '2026-06-30', 'expired', '[EXPIRED KNOWLEDGE ARTICLE] Operational guidance for sap pace of completion calculation & appeal packet checklist governed by POL-FINAID-2026-001 (v1.0).', '[SYNTHETIC DEMONSTRATION POLICY] Under legacy version 1.0 (expired 2026-06-30), students placed on financial aid suspension had 10 calendar days from term start to submit a Satisfactory Academic Progress (SAP) appeal with supporting documentation to the Office of Financial Aid & Scholarships. Operational Article KB-000001 (v1.0) specifies step-by-step intake verification for SAP Pace of Completion Calculation & Appeal Packet Checklist. Governing Policy: POL-FINAID-2026-001 v1.0 (Section 4.1 (Superseded)).', ARRAY['finaid', 'pol-finaid-2026-001', 'expired-reference']::text[], 'urn:campusresolve:synthetic-kb:kb-000001', '2026.10-seed-20261022-kb-v1.0', '2026-09-01', 'CC0-1.0 Synthetic Demonstration & Evaluation Corpus', 'Synthetic knowledge base article generated deterministically for CampusResolve AI evaluation.', 'Indexed policy section citations, normalized domain tags, and bound effective/expiration dates.', NULL, TRUE, '2025-01-01T09:00:00.000Z', '2026-09-01T08:00:00.000Z'),
  ('KB-000002', 'CAT-FINAID', 'POL-FINAID-2026-002', '2.0', 'Federal & Institutional Grant Disbursement Hold Resolution (Ref POL-FINAID-2026-002 v2.0 · #2)', '2.0', '2026-07-01', NULL, 'published', '[PUBLISHED KNOWLEDGE ARTICLE] Operational guidance for federal & institutional grant disbursement hold resolution governed by POL-FINAID-2026-002 (v2.0).', '[SYNTHETIC DEMONSTRATION POLICY] Effective July 1, 2026 (Version 2.0, superseding POL-FINAID-2026-001 v1.0), students whose cumulative GPA falls below 2.0 or pace of completion falls below 67% may submit a written Satisfactory Academic Progress (SAP) appeal within 15 business days of notification. Standard eligibility verifications are handled by the Office of Financial Aid & Scholarships; second-level SAP appeals and emergency statutory waivers must be escalated to the Financial Aid Appeals & Compliance Review Committee. Operational Article KB-000002 (v2.0) specifies step-by-step intake verification for Federal & Institutional Grant Disbursement Hold Resolution. Governing Policy: POL-FINAID-2026-002 v2.0 (Section 4.2 (Current)).', ARRAY['finaid', 'pol-finaid-2026-002', 'active-guidance']::text[], 'urn:campusresolve:synthetic-kb:kb-000002', '2026.10-seed-20261022-kb-v2.0', '2026-09-01', 'CC0-1.0 Synthetic Demonstration & Evaluation Corpus', 'Synthetic knowledge base article generated deterministically for CampusResolve AI evaluation.', 'Indexed policy section citations, normalized domain tags, and bound effective/expiration dates.', NULL, TRUE, '2026-07-01T09:00:00.000Z', '2026-09-01T08:00:00.000Z'),
  ('KB-000003', 'CAT-FINAID', 'POL-FINAID-2026-003', '1.0', 'Census Date Credit Hour Proration for Half-Time Learners (Ref POL-FINAID-2026-003 v1.0 · #3)', '2.0', '2026-01-15', NULL, 'published', '[PUBLISHED KNOWLEDGE ARTICLE] Operational guidance for census date credit hour proration for half-time learners governed by POL-FINAID-2026-003 (v1.0).', '[SYNTHETIC DEMONSTRATION POLICY] Institutional grants and federal aid disburse no earlier than 10 days prior to the official term start date, contingent upon active enrollment in at least 6 credit hours for half-time status or 12 credit hours for full-time status locked at the add/drop census deadline. Operational Article KB-000003 (v2.0) specifies step-by-step intake verification for Census Date Credit Hour Proration for Half-Time Learners. Governing Policy: POL-FINAID-2026-003 v1.0 (Section 2.3).', ARRAY['finaid', 'pol-finaid-2026-003', 'active-guidance']::text[], 'urn:campusresolve:synthetic-kb:kb-000003', '2026.10-seed-20261022-kb-v2.0', '2026-09-01', 'CC0-1.0 Synthetic Demonstration & Evaluation Corpus', 'Synthetic knowledge base article generated deterministically for CampusResolve AI evaluation.', 'Indexed policy section citations, normalized domain tags, and bound effective/expiration dates.', NULL, TRUE, '2026-01-15T09:00:00.000Z', '2026-09-01T08:00:00.000Z'),
  ('KB-000004', 'CAT-REG', 'POL-REG-2026-001', '1.0', 'Undergraduate 19–22 Credit Hour Overload Approval Workflow (Ref POL-REG-2026-001 v1.0 · #4)', '1.0', '2025-01-01', '2026-05-31', 'expired', '[EXPIRED KNOWLEDGE ARTICLE] Operational guidance for undergraduate 19–22 credit hour overload approval workflow governed by POL-REG-2026-001 (v1.0).', '[SYNTHETIC DEMONSTRATION POLICY] Under legacy version 1.0 (expired 2026-05-31), students could drop courses without a W grade through Week 3 of the semester. Operational Article KB-000004 (v1.0) specifies step-by-step intake verification for Undergraduate 19–22 Credit Hour Overload Approval Workflow. Governing Policy: POL-REG-2026-001 v1.0 (Section 3.1 (Superseded)).', ARRAY['reg', 'pol-reg-2026-001', 'expired-reference']::text[], 'urn:campusresolve:synthetic-kb:kb-000004', '2026.10-seed-20261022-kb-v1.0', '2026-09-01', 'CC0-1.0 Synthetic Demonstration & Evaluation Corpus', 'Synthetic knowledge base article generated deterministically for CampusResolve AI evaluation.', 'Indexed policy section citations, normalized domain tags, and bound effective/expiration dates.', NULL, TRUE, '2025-01-01T09:00:00.000Z', '2026-09-01T08:00:00.000Z'),
  ('KB-000005', 'CAT-REG', 'POL-REG-2026-002', '2.0', 'Cross-Departmental Prerequisite Waiver & Instructor Attestation (Ref POL-REG-2026-002 v2.0 · #5)', '2.1', '2026-06-01', NULL, 'published', '[PUBLISHED KNOWLEDGE ARTICLE] Operational guidance for cross-departmental prerequisite waiver & instructor attestation governed by POL-REG-2026-002 (v2.0).', '[SYNTHETIC DEMONSTRATION POLICY] Effective June 1, 2026 (Version 2.0, superseding POL-REG-2026-001 v1.0), standard course additions and drops without transcript notation must be completed within the first 10 business days of the term via the Office of the University Registrar. Course withdrawals with a W notation are permitted through the end of Week 8. Any retroactive withdrawal or late drop petition after Week 8 requires documented extenuating circumstances and mandatory escalation to the Academic Senate Registration Review Board. Operational Article KB-000005 (v2.1) specifies step-by-step intake verification for Cross-Departmental Prerequisite Waiver & Instructor Attestation. Governing Policy: POL-REG-2026-002 v2.0 (Section 3.2 (Current)).', ARRAY['reg', 'pol-reg-2026-002', 'active-guidance']::text[], 'urn:campusresolve:synthetic-kb:kb-000005', '2026.10-seed-20261022-kb-v2.1', '2026-09-01', 'CC0-1.0 Synthetic Demonstration & Evaluation Corpus', 'Synthetic knowledge base article generated deterministically for CampusResolve AI evaluation.', 'Indexed policy section citations, normalized domain tags, and bound effective/expiration dates.', NULL, TRUE, '2026-06-01T09:00:00.000Z', '2026-09-01T08:00:00.000Z'),
  ('KB-000006', 'CAT-REG', 'POL-REG-2026-003', '1.0', 'First-10-Business-Day Add/Drop Procedure & Roster Lock (Ref POL-REG-2026-003 v1.0 · #6)', '2.0', '2026-01-10', NULL, 'published', '[PUBLISHED KNOWLEDGE ARTICLE] Operational guidance for first-10-business-day add/drop procedure & roster lock governed by POL-REG-2026-003 (v1.0).', '[SYNTHETIC DEMONSTRATION POLICY] Standard undergraduate enrollment is capped at 18 credit hours per regular term. Requests to enroll in 19 to 22 credit hours require a minimum cumulative GPA of 3.30 and advisor attestation processed by the Office of the University Registrar. Operational Article KB-000006 (v2.0) specifies step-by-step intake verification for First-10-Business-Day Add/Drop Procedure & Roster Lock. Governing Policy: POL-REG-2026-003 v1.0 (Section 5.4).', ARRAY['reg', 'pol-reg-2026-003', 'active-guidance']::text[], 'urn:campusresolve:synthetic-kb:kb-000006', '2026.10-seed-20261022-kb-v2.0', '2026-09-01', 'CC0-1.0 Synthetic Demonstration & Evaluation Corpus', 'Synthetic knowledge base article generated deterministically for CampusResolve AI evaluation.', 'Indexed policy section citations, normalized domain tags, and bound effective/expiration dates.', NULL, TRUE, '2026-01-10T09:00:00.000Z', '2026-09-01T08:00:00.000Z'),
  ('KB-000007', 'CAT-IT', 'POL-IT-2026-001', '1.0', 'Identity Verification for Locked Institutional SSO Accounts (Ref POL-IT-2026-001 v1.0 · #7)', '1.0', '2025-01-01', '2026-04-30', 'expired', '[EXPIRED KNOWLEDGE ARTICLE] Operational guidance for identity verification for locked institutional sso accounts governed by POL-IT-2026-001 (v1.0).', '[SYNTHETIC DEMONSTRATION POLICY] Under legacy version 1.0 (expired 2026-04-30), SMS text codes were permitted as a primary multi-factor authentication method for institutional accounts. Operational Article KB-000007 (v1.0) specifies step-by-step intake verification for Identity Verification for Locked Institutional SSO Accounts. Governing Policy: POL-IT-2026-001 v1.0 (Section 1.1 (Superseded)).', ARRAY['it', 'pol-it-2026-001', 'expired-reference']::text[], 'urn:campusresolve:synthetic-kb:kb-000007', '2026.10-seed-20261022-kb-v1.0', '2026-09-01', 'CC0-1.0 Synthetic Demonstration & Evaluation Corpus', 'Synthetic knowledge base article generated deterministically for CampusResolve AI evaluation.', 'Indexed policy section citations, normalized domain tags, and bound effective/expiration dates.', NULL, TRUE, '2025-01-01T09:00:00.000Z', '2026-09-01T08:00:00.000Z'),
  ('KB-000008', 'CAT-IT', 'POL-IT-2026-002', '2.0', 'LMS Course Shell Provisioning & 4-Hour Roster Sync Troubleshooting (Ref POL-IT-2026-002 v2.0 · #8)', '2.0', '2026-05-01', NULL, 'published', '[PUBLISHED KNOWLEDGE ARTICLE] Operational guidance for lms course shell provisioning & 4-hour roster sync troubleshooting governed by POL-IT-2026-002 (v2.0).', '[SYNTHETIC DEMONSTRATION POLICY] Effective May 1, 2026 (Version 2.0, superseding POL-IT-2026-001 v1.0), all learners, instructors, and staff must use FIDO2 passkeys or TOTP authenticator apps for Single Sign-On (SSO). Routine MFA device resets are handled by the Campus IT Operations & Identity Desk after photo-ID verification. Suspected account compromise or privilege anomalies must be escalated immediately to the Information Security & Infrastructure Escalation Unit. Operational Article KB-000008 (v2.0) specifies step-by-step intake verification for LMS Course Shell Provisioning & 4-Hour Roster Sync Troubleshooting. Governing Policy: POL-IT-2026-002 v2.0 (Section 1.2 (Current)).', ARRAY['it', 'pol-it-2026-002', 'active-guidance']::text[], 'urn:campusresolve:synthetic-kb:kb-000008', '2026.10-seed-20261022-kb-v2.0', '2026-09-01', 'CC0-1.0 Synthetic Demonstration & Evaluation Corpus', 'Synthetic knowledge base article generated deterministically for CampusResolve AI evaluation.', 'Indexed policy section citations, normalized domain tags, and bound effective/expiration dates.', NULL, TRUE, '2026-05-01T09:00:00.000Z', '2026-09-01T08:00:00.000Z'),
  ('KB-000009', 'CAT-IT', 'POL-IT-2026-003', '1.0', 'Instructional Lab Software Floating License Seat Allocation (Ref POL-IT-2026-003 v1.0 · #9)', '2.0', '2026-01-15', NULL, 'published', '[PUBLISHED KNOWLEDGE ARTICLE] Operational guidance for instructional lab software floating license seat allocation governed by POL-IT-2026-003 (v1.0).', '[SYNTHETIC DEMONSTRATION POLICY] LMS course shells are provisioned 30 days before term start and synchronize roster changes every 4 hours with the Registrar feed. Special seat allocations for instructional lab software are fulfilled by the Campus IT Operations & Identity Desk. Operational Article KB-000009 (v2.0) specifies step-by-step intake verification for Instructional Lab Software Floating License Seat Allocation. Governing Policy: POL-IT-2026-003 v1.0 (Section 6.1).', ARRAY['it', 'pol-it-2026-003', 'active-guidance']::text[], 'urn:campusresolve:synthetic-kb:kb-000009', '2026.10-seed-20261022-kb-v2.0', '2026-09-01', 'CC0-1.0 Synthetic Demonstration & Evaluation Corpus', 'Synthetic knowledge base article generated deterministically for CampusResolve AI evaluation.', 'Indexed policy section citations, normalized domain tags, and bound effective/expiration dates.', NULL, TRUE, '2026-01-15T09:00:00.000Z', '2026-09-01T08:00:00.000Z'),
  ('KB-000010', 'CAT-ACCESS', 'POL-ACCESS-2026-001', '1.0', 'Assistive Screen-Reader PDF Remediation Turnaround Standards (Ref POL-ACCESS-2026-001 v1.0 · #10)', '1.0', '2025-01-01', '2026-06-15', 'expired', '[EXPIRED KNOWLEDGE ARTICLE] Operational guidance for assistive screen-reader pdf remediation turnaround standards governed by POL-ACCESS-2026-001 (v1.0).', '[SYNTHETIC DEMONSTRATION POLICY] Under legacy version 1.0 (expired 2026-06-15), students were required to submit proctored exam accommodation booking requests 14 calendar days prior to the examination date. Operational Article KB-000010 (v1.0) specifies step-by-step intake verification for Assistive Screen-Reader PDF Remediation Turnaround Standards. Governing Policy: POL-ACCESS-2026-001 v1.0 (Section 7.1 (Superseded)).', ARRAY['access', 'pol-access-2026-001', 'expired-reference']::text[], 'urn:campusresolve:synthetic-kb:kb-000010', '2026.10-seed-20261022-kb-v1.0', '2026-09-01', 'CC0-1.0 Synthetic Demonstration & Evaluation Corpus', 'Synthetic knowledge base article generated deterministically for CampusResolve AI evaluation.', 'Indexed policy section citations, normalized domain tags, and bound effective/expiration dates.', NULL, TRUE, '2025-01-01T09:00:00.000Z', '2026-09-01T08:00:00.000Z'),
  ('KB-000011', 'CAT-ACCESS', 'POL-ACCESS-2026-002', '2.0', '5-Business-Day Proctored Testing Accommodation Booking Guide (Ref POL-ACCESS-2026-002 v2.0 · #11)', '2.0', '2026-06-16', NULL, 'published', '[PUBLISHED KNOWLEDGE ARTICLE] Operational guidance for 5-business-day proctored testing accommodation booking guide governed by POL-ACCESS-2026-002 (v2.0).', '[SYNTHETIC DEMONSTRATION POLICY] Effective June 16, 2026 (Version 2.0, superseding POL-ACCESS-2026-001 v1.0), students holding approved accommodation letters from the Disability & Accessibility Services Office must submit proctored exam scheduling requests at least 5 business days before the exam. Accommodation implementation disputes, denials, or urgent barrier reports must be escalated to the ADA / Section 504 Compliance Review Panel. Operational Article KB-000011 (v2.0) specifies step-by-step intake verification for 5-Business-Day Proctored Testing Accommodation Booking Guide. Governing Policy: POL-ACCESS-2026-002 v2.0 (Section 7.2 (Current)).', ARRAY['access', 'pol-access-2026-002', 'active-guidance']::text[], 'urn:campusresolve:synthetic-kb:kb-000011', '2026.10-seed-20261022-kb-v2.0', '2026-09-01', 'CC0-1.0 Synthetic Demonstration & Evaluation Corpus', 'Synthetic knowledge base article generated deterministically for CampusResolve AI evaluation.', 'Indexed policy section citations, normalized domain tags, and bound effective/expiration dates.', NULL, TRUE, '2026-06-16T09:00:00.000Z', '2026-09-01T08:00:00.000Z'),
  ('KB-000012', 'CAT-ACCESS', 'POL-ACCESS-2026-003', '1.0', 'Requesting Real-Time CART Captioning & Accessible Course Packets (Ref POL-ACCESS-2026-003 v1.0 · #12)', '2.0', '2026-01-15', NULL, 'published', '[PUBLISHED KNOWLEDGE ARTICLE] Operational guidance for requesting real-time cart captioning & accessible course packets governed by POL-ACCESS-2026-003 (v1.0).', '[SYNTHETIC DEMONSTRATION POLICY] The Disability & Accessibility Services Office coordinates real-time CART captioning, Braille/tactile graphics conversion, and screen-reader accessible PDF remediation for enrolled learners within 3 business days of request intake. Operational Article KB-000012 (v2.0) specifies step-by-step intake verification for Requesting Real-Time CART Captioning & Accessible Course Packets. Governing Policy: POL-ACCESS-2026-003 v1.0 (Section 8.3).', ARRAY['access', 'pol-access-2026-003', 'active-guidance']::text[], 'urn:campusresolve:synthetic-kb:kb-000012', '2026.10-seed-20261022-kb-v2.0', '2026-09-01', 'CC0-1.0 Synthetic Demonstration & Evaluation Corpus', 'Synthetic knowledge base article generated deterministically for CampusResolve AI evaluation.', 'Indexed policy section citations, normalized domain tags, and bound effective/expiration dates.', NULL, TRUE, '2026-01-15T09:00:00.000Z', '2026-09-01T08:00:00.000Z'),
  ('KB-000013', 'CAT-FINAID', 'POL-FINAID-2026-001', '1.0', 'Census Date Credit Hour Proration for Half-Time Learners (Ref POL-FINAID-2026-001 v1.0 · #13)', '1.0', '2025-01-01', '2026-06-30', 'expired', '[EXPIRED KNOWLEDGE ARTICLE] Operational guidance for census date credit hour proration for half-time learners governed by POL-FINAID-2026-001 (v1.0).', '[SYNTHETIC DEMONSTRATION POLICY] Under legacy version 1.0 (expired 2026-06-30), students placed on financial aid suspension had 10 calendar days from term start to submit a Satisfactory Academic Progress (SAP) appeal with supporting documentation to the Office of Financial Aid & Scholarships. Operational Article KB-000013 (v1.0) specifies step-by-step intake verification for Census Date Credit Hour Proration for Half-Time Learners. Governing Policy: POL-FINAID-2026-001 v1.0 (Section 4.1 (Superseded)).', ARRAY['finaid', 'pol-finaid-2026-001', 'expired-reference']::text[], 'urn:campusresolve:synthetic-kb:kb-000013', '2026.10-seed-20261022-kb-v1.0', '2026-09-01', 'CC0-1.0 Synthetic Demonstration & Evaluation Corpus', 'Synthetic knowledge base article generated deterministically for CampusResolve AI evaluation.', 'Indexed policy section citations, normalized domain tags, and bound effective/expiration dates.', NULL, TRUE, '2025-01-01T09:00:00.000Z', '2026-09-01T08:00:00.000Z'),
  ('KB-000014', 'CAT-FINAID', 'POL-FINAID-2026-002', '2.0', 'Emergency Hardship Financial Aid Re-Evaluation Procedure (Ref POL-FINAID-2026-002 v2.0 · #14)', '2.0', '2026-07-01', NULL, 'published', '[PUBLISHED KNOWLEDGE ARTICLE] Operational guidance for emergency hardship financial aid re-evaluation procedure governed by POL-FINAID-2026-002 (v2.0).', '[SYNTHETIC DEMONSTRATION POLICY] Effective July 1, 2026 (Version 2.0, superseding POL-FINAID-2026-001 v1.0), students whose cumulative GPA falls below 2.0 or pace of completion falls below 67% may submit a written Satisfactory Academic Progress (SAP) appeal within 15 business days of notification. Standard eligibility verifications are handled by the Office of Financial Aid & Scholarships; second-level SAP appeals and emergency statutory waivers must be escalated to the Financial Aid Appeals & Compliance Review Committee. Operational Article KB-000014 (v2.0) specifies step-by-step intake verification for Emergency Hardship Financial Aid Re-Evaluation Procedure. Governing Policy: POL-FINAID-2026-002 v2.0 (Section 4.2 (Current)).', ARRAY['finaid', 'pol-finaid-2026-002', 'active-guidance']::text[], 'urn:campusresolve:synthetic-kb:kb-000014', '2026.10-seed-20261022-kb-v2.0', '2026-09-01', 'CC0-1.0 Synthetic Demonstration & Evaluation Corpus', 'Synthetic knowledge base article generated deterministically for CampusResolve AI evaluation.', 'Indexed policy section citations, normalized domain tags, and bound effective/expiration dates.', NULL, TRUE, '2026-07-01T09:00:00.000Z', '2026-09-01T08:00:00.000Z'),
  ('KB-000015', 'CAT-FINAID', 'POL-FINAID-2026-003', '1.0', 'Scholarship Renewal GPA Verification & Grace Term Rules (Ref POL-FINAID-2026-003 v1.0 · #15)', '2.1', '2026-01-15', NULL, 'published', '[PUBLISHED KNOWLEDGE ARTICLE] Operational guidance for scholarship renewal gpa verification & grace term rules governed by POL-FINAID-2026-003 (v1.0).', '[SYNTHETIC DEMONSTRATION POLICY] Institutional grants and federal aid disburse no earlier than 10 days prior to the official term start date, contingent upon active enrollment in at least 6 credit hours for half-time status or 12 credit hours for full-time status locked at the add/drop census deadline. Operational Article KB-000015 (v2.1) specifies step-by-step intake verification for Scholarship Renewal GPA Verification & Grace Term Rules. Governing Policy: POL-FINAID-2026-003 v1.0 (Section 2.3).', ARRAY['finaid', 'pol-finaid-2026-003', 'active-guidance']::text[], 'urn:campusresolve:synthetic-kb:kb-000015', '2026.10-seed-20261022-kb-v2.1', '2026-09-01', 'CC0-1.0 Synthetic Demonstration & Evaluation Corpus', 'Synthetic knowledge base article generated deterministically for CampusResolve AI evaluation.', 'Indexed policy section citations, normalized domain tags, and bound effective/expiration dates.', NULL, TRUE, '2026-01-15T09:00:00.000Z', '2026-09-01T08:00:00.000Z'),
  ('KB-000016', 'CAT-REG', 'POL-REG-2026-001', '1.0', 'First-10-Business-Day Add/Drop Procedure & Roster Lock (Ref POL-REG-2026-001 v1.0 · #16)', '1.0', '2025-01-01', '2026-05-31', 'expired', '[EXPIRED KNOWLEDGE ARTICLE] Operational guidance for first-10-business-day add/drop procedure & roster lock governed by POL-REG-2026-001 (v1.0).', '[SYNTHETIC DEMONSTRATION POLICY] Under legacy version 1.0 (expired 2026-05-31), students could drop courses without a W grade through Week 3 of the semester. Operational Article KB-000016 (v1.0) specifies step-by-step intake verification for First-10-Business-Day Add/Drop Procedure & Roster Lock. Governing Policy: POL-REG-2026-001 v1.0 (Section 3.1 (Superseded)).', ARRAY['reg', 'pol-reg-2026-001', 'expired-reference']::text[], 'urn:campusresolve:synthetic-kb:kb-000016', '2026.10-seed-20261022-kb-v1.0', '2026-09-01', 'CC0-1.0 Synthetic Demonstration & Evaluation Corpus', 'Synthetic knowledge base article generated deterministically for CampusResolve AI evaluation.', 'Indexed policy section citations, normalized domain tags, and bound effective/expiration dates.', NULL, TRUE, '2025-01-01T09:00:00.000Z', '2026-09-01T08:00:00.000Z'),
  ('KB-000017', 'CAT-REG', 'POL-REG-2026-002', '2.0', 'Week 8 Course Withdrawal (W Grade) Online Submission Guide (Ref POL-REG-2026-002 v2.0 · #17)', '2.0', '2026-06-01', NULL, 'published', '[PUBLISHED KNOWLEDGE ARTICLE] Operational guidance for week 8 course withdrawal (w grade) online submission guide governed by POL-REG-2026-002 (v2.0).', '[SYNTHETIC DEMONSTRATION POLICY] Effective June 1, 2026 (Version 2.0, superseding POL-REG-2026-001 v1.0), standard course additions and drops without transcript notation must be completed within the first 10 business days of the term via the Office of the University Registrar. Course withdrawals with a W notation are permitted through the end of Week 8. Any retroactive withdrawal or late drop petition after Week 8 requires documented extenuating circumstances and mandatory escalation to the Academic Senate Registration Review Board. Operational Article KB-000017 (v2.0) specifies step-by-step intake verification for Week 8 Course Withdrawal (W Grade) Online Submission Guide. Governing Policy: POL-REG-2026-002 v2.0 (Section 3.2 (Current)).', ARRAY['reg', 'pol-reg-2026-002', 'active-guidance']::text[], 'urn:campusresolve:synthetic-kb:kb-000017', '2026.10-seed-20261022-kb-v2.0', '2026-09-01', 'CC0-1.0 Synthetic Demonstration & Evaluation Corpus', 'Synthetic knowledge base article generated deterministically for CampusResolve AI evaluation.', 'Indexed policy section citations, normalized domain tags, and bound effective/expiration dates.', NULL, TRUE, '2026-06-01T09:00:00.000Z', '2026-09-01T08:00:00.000Z'),
  ('KB-000018', 'CAT-REG', 'POL-REG-2026-003', '1.0', 'Post-Deadline Retroactive Withdrawal Petition Documentation (Ref POL-REG-2026-003 v1.0 · #18)', '2.0', '2026-01-10', NULL, 'published', '[PUBLISHED KNOWLEDGE ARTICLE] Operational guidance for post-deadline retroactive withdrawal petition documentation governed by POL-REG-2026-003 (v1.0).', '[SYNTHETIC DEMONSTRATION POLICY] Standard undergraduate enrollment is capped at 18 credit hours per regular term. Requests to enroll in 19 to 22 credit hours require a minimum cumulative GPA of 3.30 and advisor attestation processed by the Office of the University Registrar. Operational Article KB-000018 (v2.0) specifies step-by-step intake verification for Post-Deadline Retroactive Withdrawal Petition Documentation. Governing Policy: POL-REG-2026-003 v1.0 (Section 5.4).', ARRAY['reg', 'pol-reg-2026-003', 'active-guidance']::text[], 'urn:campusresolve:synthetic-kb:kb-000018', '2026.10-seed-20261022-kb-v2.0', '2026-09-01', 'CC0-1.0 Synthetic Demonstration & Evaluation Corpus', 'Synthetic knowledge base article generated deterministically for CampusResolve AI evaluation.', 'Indexed policy section citations, normalized domain tags, and bound effective/expiration dates.', NULL, TRUE, '2026-01-10T09:00:00.000Z', '2026-09-01T08:00:00.000Z'),
  ('KB-000019', 'CAT-IT', 'POL-IT-2026-001', '1.0', 'Instructional Lab Software Floating License Seat Allocation (Ref POL-IT-2026-001 v1.0 · #19)', '1.0', '2025-01-01', '2026-04-30', 'expired', '[EXPIRED KNOWLEDGE ARTICLE] Operational guidance for instructional lab software floating license seat allocation governed by POL-IT-2026-001 (v1.0).', '[SYNTHETIC DEMONSTRATION POLICY] Under legacy version 1.0 (expired 2026-04-30), SMS text codes were permitted as a primary multi-factor authentication method for institutional accounts. Operational Article KB-000019 (v1.0) specifies step-by-step intake verification for Instructional Lab Software Floating License Seat Allocation. Governing Policy: POL-IT-2026-001 v1.0 (Section 1.1 (Superseded)).', ARRAY['it', 'pol-it-2026-001', 'expired-reference']::text[], 'urn:campusresolve:synthetic-kb:kb-000019', '2026.10-seed-20261022-kb-v1.0', '2026-09-01', 'CC0-1.0 Synthetic Demonstration & Evaluation Corpus', 'Synthetic knowledge base article generated deterministically for CampusResolve AI evaluation.', 'Indexed policy section citations, normalized domain tags, and bound effective/expiration dates.', NULL, TRUE, '2025-01-01T09:00:00.000Z', '2026-09-01T08:00:00.000Z'),
  ('KB-000020', 'CAT-IT', 'POL-IT-2026-002', '2.0', 'Reporting Suspected Phishing or Unauthorized Token Escalation (Ref POL-IT-2026-002 v2.0 · #20)', '2.1', '2026-05-01', NULL, 'published', '[PUBLISHED KNOWLEDGE ARTICLE] Operational guidance for reporting suspected phishing or unauthorized token escalation governed by POL-IT-2026-002 (v2.0).', '[SYNTHETIC DEMONSTRATION POLICY] Effective May 1, 2026 (Version 2.0, superseding POL-IT-2026-001 v1.0), all learners, instructors, and staff must use FIDO2 passkeys or TOTP authenticator apps for Single Sign-On (SSO). Routine MFA device resets are handled by the Campus IT Operations & Identity Desk after photo-ID verification. Suspected account compromise or privilege anomalies must be escalated immediately to the Information Security & Infrastructure Escalation Unit. Operational Article KB-000020 (v2.1) specifies step-by-step intake verification for Reporting Suspected Phishing or Unauthorized Token Escalation. Governing Policy: POL-IT-2026-002 v2.0 (Section 1.2 (Current)).', ARRAY['it', 'pol-it-2026-002', 'active-guidance']::text[], 'urn:campusresolve:synthetic-kb:kb-000020', '2026.10-seed-20261022-kb-v2.1', '2026-09-01', 'CC0-1.0 Synthetic Demonstration & Evaluation Corpus', 'Synthetic knowledge base article generated deterministically for CampusResolve AI evaluation.', 'Indexed policy section citations, normalized domain tags, and bound effective/expiration dates.', NULL, TRUE, '2026-05-01T09:00:00.000Z', '2026-09-01T08:00:00.000Z'),
  ('KB-000021', 'CAT-IT', 'POL-IT-2026-003', '1.0', 'Transitioning from Legacy SMS to FIDO2 / TOTP Authenticator MFA (Ref POL-IT-2026-003 v1.0 · #21)', '2.0', '2026-01-15', NULL, 'published', '[PUBLISHED KNOWLEDGE ARTICLE] Operational guidance for transitioning from legacy sms to fido2 / totp authenticator mfa governed by POL-IT-2026-003 (v1.0).', '[SYNTHETIC DEMONSTRATION POLICY] LMS course shells are provisioned 30 days before term start and synchronize roster changes every 4 hours with the Registrar feed. Special seat allocations for instructional lab software are fulfilled by the Campus IT Operations & Identity Desk. Operational Article KB-000021 (v2.0) specifies step-by-step intake verification for Transitioning from Legacy SMS to FIDO2 / TOTP Authenticator MFA. Governing Policy: POL-IT-2026-003 v1.0 (Section 6.1).', ARRAY['it', 'pol-it-2026-003', 'active-guidance']::text[], 'urn:campusresolve:synthetic-kb:kb-000021', '2026.10-seed-20261022-kb-v2.0', '2026-09-01', 'CC0-1.0 Synthetic Demonstration & Evaluation Corpus', 'Synthetic knowledge base article generated deterministically for CampusResolve AI evaluation.', 'Indexed policy section citations, normalized domain tags, and bound effective/expiration dates.', NULL, TRUE, '2026-01-15T09:00:00.000Z', '2026-09-01T08:00:00.000Z'),
  ('KB-000022', 'CAT-ACCESS', 'POL-ACCESS-2026-001', '1.0', 'Requesting Real-Time CART Captioning & Accessible Course Packets (Ref POL-ACCESS-2026-001 v1.0 · #22)', '1.0', '2025-01-01', '2026-06-15', 'expired', '[EXPIRED KNOWLEDGE ARTICLE] Operational guidance for requesting real-time cart captioning & accessible course packets governed by POL-ACCESS-2026-001 (v1.0).', '[SYNTHETIC DEMONSTRATION POLICY] Under legacy version 1.0 (expired 2026-06-15), students were required to submit proctored exam accommodation booking requests 14 calendar days prior to the examination date. Operational Article KB-000022 (v1.0) specifies step-by-step intake verification for Requesting Real-Time CART Captioning & Accessible Course Packets. Governing Policy: POL-ACCESS-2026-001 v1.0 (Section 7.1 (Superseded)).', ARRAY['access', 'pol-access-2026-001', 'expired-reference']::text[], 'urn:campusresolve:synthetic-kb:kb-000022', '2026.10-seed-20261022-kb-v1.0', '2026-09-01', 'CC0-1.0 Synthetic Demonstration & Evaluation Corpus', 'Synthetic knowledge base article generated deterministically for CampusResolve AI evaluation.', 'Indexed policy section citations, normalized domain tags, and bound effective/expiration dates.', NULL, TRUE, '2025-01-01T09:00:00.000Z', '2026-09-01T08:00:00.000Z'),
  ('KB-000023', 'CAT-ACCESS', 'POL-ACCESS-2026-002', '2.0', 'Instructor Notification Letters for Approved Exam Extended Time (Ref POL-ACCESS-2026-002 v2.0 · #23)', '2.0', '2026-06-16', NULL, 'published', '[PUBLISHED KNOWLEDGE ARTICLE] Operational guidance for instructor notification letters for approved exam extended time governed by POL-ACCESS-2026-002 (v2.0).', '[SYNTHETIC DEMONSTRATION POLICY] Effective June 16, 2026 (Version 2.0, superseding POL-ACCESS-2026-001 v1.0), students holding approved accommodation letters from the Disability & Accessibility Services Office must submit proctored exam scheduling requests at least 5 business days before the exam. Accommodation implementation disputes, denials, or urgent barrier reports must be escalated to the ADA / Section 504 Compliance Review Panel. Operational Article KB-000023 (v2.0) specifies step-by-step intake verification for Instructor Notification Letters for Approved Exam Extended Time. Governing Policy: POL-ACCESS-2026-002 v2.0 (Section 7.2 (Current)).', ARRAY['access', 'pol-access-2026-002', 'active-guidance']::text[], 'urn:campusresolve:synthetic-kb:kb-000023', '2026.10-seed-20261022-kb-v2.0', '2026-09-01', 'CC0-1.0 Synthetic Demonstration & Evaluation Corpus', 'Synthetic knowledge base article generated deterministically for CampusResolve AI evaluation.', 'Indexed policy section citations, normalized domain tags, and bound effective/expiration dates.', NULL, TRUE, '2026-06-16T09:00:00.000Z', '2026-09-01T08:00:00.000Z'),
  ('KB-000024', 'CAT-ACCESS', 'POL-ACCESS-2026-003', '1.0', 'Escalating Accommodation Implementation Barriers to Section 504 Panel (Ref POL-ACCESS-2026-003 v1.0 · #24)', '2.0', '2026-01-15', NULL, 'published', '[PUBLISHED KNOWLEDGE ARTICLE] Operational guidance for escalating accommodation implementation barriers to section 504 panel governed by POL-ACCESS-2026-003 (v1.0).', '[SYNTHETIC DEMONSTRATION POLICY] The Disability & Accessibility Services Office coordinates real-time CART captioning, Braille/tactile graphics conversion, and screen-reader accessible PDF remediation for enrolled learners within 3 business days of request intake. Operational Article KB-000024 (v2.0) specifies step-by-step intake verification for Escalating Accommodation Implementation Barriers to Section 504 Panel. Governing Policy: POL-ACCESS-2026-003 v1.0 (Section 8.3).', ARRAY['access', 'pol-access-2026-003', 'active-guidance']::text[], 'urn:campusresolve:synthetic-kb:kb-000024', '2026.10-seed-20261022-kb-v2.0', '2026-09-01', 'CC0-1.0 Synthetic Demonstration & Evaluation Corpus', 'Synthetic knowledge base article generated deterministically for CampusResolve AI evaluation.', 'Indexed policy section citations, normalized domain tags, and bound effective/expiration dates.', NULL, TRUE, '2026-01-15T09:00:00.000Z', '2026-09-01T08:00:00.000Z')
