  ('TKT-2026-000001', 'REQ-2026-000001', NULL, 'CAT-FINAID', 'Financial Aid', 'TERM-2026-FALL', 'Financial Aid Operational Inquiry: Satisfactory Academic Progress (SAP) & Financial Aid Appeal Policy', 'Requester Julian Alvarez (REQ-2026-000001) requests policy-grounded verification regarding Satisfactory Academic Progress (SAP) & Financial Aid Appeal Policy (Section 4.2 (Current)) for term TERM-2026-FALL.', 'Standard Priority', 'resolved', 'Financial Aid Appeals & Compliance Review Committee', 'RULE-FINAID-001', 'POL-FINAID-2026-002', '2.0', 'KB-000002', '2.0', FALSE, FALSE, NULL, 'Resolved in accordance with POL-FINAID-2026-002 v2.0 (Section 4.2 (Current)) and KB-000002 v2.0.', TRUE, '2026-09-01T14:07:00.000Z', '2026-09-01T17:07:00.000Z', '2026-09-01T17:07:00.000Z', NULL),
